func TestMicEDecode(t *testing.T) {
	for _, v := range micEVectors {
		lat, lon, sym, course, _, ok := micEDecode(v.dest, v.info)
		if !ok {
			t.Errorf("%q %q: decode failed", v.dest, v.info)
			continue
		}
		if math.Abs(lat-v.lat) > 0.0002 || math.Abs(lon-v.lon) > 0.0002 {
			t.Errorf("%q: got %.5f,%.5f want %.5f,%.5f", v.dest, lat, lon, v.lat, v.lon)
		}
		if sym != v.sym {
			t.Errorf("%q: symbol %q want %q", v.dest, sym, v.sym)
		}
		if course != v.course {
			t.Errorf("%q: course %d want %d", v.dest, course, v.course)
		}
	}
}

func TestMicEViaParsePacket(t *testing.T) {
	v := micEVectors[0] // UK, 53.715 N 1.535 W
	hp, ok := parsePacket("M0TST-9>" + v.dest + ",WIDE1-1:" + v.info)
	if !ok || math.Abs(hp.Lat-v.lat) > 0.0002 || math.Abs(hp.Lon-v.lon) > 0.0002 || hp.Symbol != v.sym {
		t.Fatalf("parsePacket mic-e: ok=%v lat=%.5f lon=%.5f sym=%q", ok, hp.Lat, hp.Lon, hp.Symbol)
	}
}

func TestMicERejectsGarbage(t *testing.T) {
	for _, c := range [][2]string{{"ABC", "`abcdefgh"}, {"U3TRYQ", "`short"}, {"U3TRYQ", "!notmice12"}} {
		if _, _, _, _, _, ok := micEDecode(c[0], c[1]); ok {
			t.Errorf("accepted garbage %q %q", c[0], c[1])
		}
	}
}

func TestCompressedOverlayDigits(t *testing.T) {
	// APRS spec example compressed position (49.5N 72.75W) with symbol table 'a'
	// (= overlay '0') and symbol code '>'.
	hp, ok := parsePacket("M0LRA>APLRT1,TCPIP*:!a5L!!<*e7>7P[")
	if !ok {
		t.Fatalf("compressed packet with a-j table not parsed")
	}
	if hp.Symbol != "0>" {
		t.Errorf("symbol %q, want normalised overlay \"0>\"", hp.Symbol)
	}
}
